<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref} from 'vue'
import {http,errorText} from '../api/client'
import OperationGuide from './OperationGuide.vue'
import portrait from '../assets/c-dou-transparent.png'
const bouncing=ref(false)
const open=ref(false),tab=ref('chat'),bubble=ref(true),busy=ref(false),draft=ref(''),failure=ref(''),hidden=ref(false)
const welcome='你好呀，我是 C豆！有什么录单问题，都可以问我哦～'
type Message={role:'user'|'assistant';content:string}
const messages=ref<Message[]>([]),log=ref<HTMLElement>(),pet=ref<HTMLButtonElement>(),input=ref<HTMLTextAreaElement>()
const x=ref(0),y=ref(0),vw=ref(window.innerWidth),vh=ref(window.innerHeight),dragging=ref(false)
const size=76
let timer:ReturnType<typeof setTimeout>|undefined,controller:AbortController|undefined
let gesture:{id:number;sx:number;sy:number;x:number;y:number;moved:boolean}|undefined
const questions=['什么是翻单？','如何上传 Excel 采购订单？','A/B/C 客户的默认匹配规则是什么？','如何自定义客户匹配字段？','历史订单试匹配有什么作用？','为什么会出现未匹配？','为什么需要人工确认重复采购？','如何查看已经创建的销售订单？']
const panelStyle=computed(()=>({left:Math.max(8,Math.min(x.value-300,vw.value-Math.min(390,vw.value-16)-8))+'px',top:Math.max(8,Math.min(y.value-540,vh.value-Math.min(560,vh.value-16)-8))+'px'}))
const bubbleStyle=computed(()=>({left:Math.max(8,Math.min(x.value-110,vw.value-220))+'px',top:(y.value<65?y.value+size+8:y.value-52)+'px'}))
function clamp(a:number,b:number){return {x:Math.max(0,Math.min(a,vw.value-size)),y:Math.max(0,Math.min(b,vh.value-size))}}
function paint(a:number,b:number){if(pet.value)pet.value.style.transform=`translate3d(${a}px,${b}px,0)`}
function resize(){vw.value=window.innerWidth;vh.value=window.innerHeight;const pos=clamp(x.value,y.value);x.value=pos.x;y.value=pos.y;paint(pos.x,pos.y)}
function save(){try{localStorage.setItem('cvte-cdou-position',JSON.stringify({x:x.value,y:y.value}))}catch{/* optional storage */}}
function down(e:PointerEvent){if(!e.isPrimary||e.button!==0)return;gesture={id:e.pointerId,sx:e.clientX,sy:e.clientY,x:x.value,y:y.value,moved:false};pet.value?.setPointerCapture?.(e.pointerId)}
function move(e:PointerEvent){if(!gesture||e.pointerId!==gesture.id)return;const dx=e.clientX-gesture.sx,dy=e.clientY-gesture.sy;if(Math.hypot(dx,dy)>6)gesture.moved=true;if(gesture.moved){dragging.value=true;bubble.value=false;const pos=clamp(gesture.x+dx,gesture.y+dy);paint(pos.x,pos.y)}}
function end(e:PointerEvent,cancel=false){if(!gesture||e.pointerId!==gesture.id)return;const g=gesture;gesture=undefined;if(g.moved){const pos=clamp(g.x+e.clientX-g.sx,g.y+e.clientY-g.sy);x.value=pos.x;y.value=pos.y;paint(pos.x,pos.y);save()}else if(!cancel)toggle();dragging.value=false;pet.value?.releasePointerCapture?.(e.pointerId)}
function toggle(){bouncing.value=true;open.value=!open.value;bubble.value=false;if(open.value)nextTick(()=>input.value?.focus())}
function hint(){if(open.value||dragging.value)return;bubble.value=true;clearTimeout(timer);timer=setTimeout(()=>bubble.value=false,4500)}
function visibility(){hidden.value=document.hidden}
async function scroll(){await nextTick();log.value?.scrollTo?.({top:log.value.scrollHeight})}
const history=()=>{const result:Message[]=[];for(let i=0;i+1<messages.value.length;i+=2){const a=messages.value[i]!,b=messages.value[i+1]!;if(a.role==='user'&&b.role==='assistant')result.push(a,b)}let recent=result.slice(-10);while(recent.reduce((n,m)=>n+m.content.length,0)>12000)recent=recent.slice(2);return recent}
async function send(text=draft.value,retry=false){text=text.trim();if(busy.value||!text||text.length>2000)return;const previous=history();if(!retry)messages.value.push({role:'user',content:text});draft.value='';failure.value='';busy.value=true;controller=new AbortController();await scroll();try{const {data}=await http.post('/api/v1/assistant/chat',{message:text,history:previous},{timeout:125000,signal:controller.signal});messages.value.push({role:'assistant',content:data.data.reply})}catch(e){if(!controller.signal.aborted)failure.value=errorText(e)}finally{busy.value=false;controller=undefined;await scroll()}}
function retry(){const last=messages.value.at(-1);if(last?.role==='user')void send(last.content,true)}
function clear(){if(busy.value)return;messages.value=[];failure.value=''}
function key(e:KeyboardEvent){if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();void send()}}
onMounted(()=>{x.value=vw.value-size-22;y.value=vh.value-size-22;try{const saved=JSON.parse(localStorage.getItem('cvte-cdou-position')||'null');if(Number.isFinite(saved?.x)&&Number.isFinite(saved?.y)){x.value=saved.x;y.value=saved.y}}catch{/* default position */}resize();hint();window.addEventListener('resize',resize);document.addEventListener('visibilitychange',visibility);visibility()})
onBeforeUnmount(()=>{clearTimeout(timer);controller?.abort();window.removeEventListener('resize',resize);document.removeEventListener('visibilitychange',visibility)})
</script>
<template>
<div class="cdou" :class="{paused:hidden,dragging}" @keydown.esc="open=false">
 <Transition name="soft"><div v-if="bubble&&!open" class="pet-bubble" :style="bubbleStyle">有什么问题可以问 C豆哦～</div></Transition>
 <button ref="pet" class="pet" aria-label="打开 C豆智能助手" :aria-expanded="open" @pointerdown="down" @pointermove="move" @pointerup="end($event)" @pointercancel="end($event,true)" @lostpointercapture="gesture=undefined;dragging=false" @click="e=>{if(e.detail===0)toggle()}" @mouseenter="hint" @dragstart.prevent><span class="pet-hover" :class="{bouncing}" @animationend="bouncing=false"><img :src="portrait" alt="C豆" draggable="false" /></span></button>
 <Transition name="soft"><section v-if="open" class="assistant-panel" :style="panelStyle" aria-label="C豆 · 录单智能助手">
  <header><img :src="portrait" alt=""/><div><strong>C豆 · 录单智能助手</strong><small>陪你理清每一步录单</small></div><button aria-label="关闭 C豆" @click="open=false">×</button></header>
  <nav class="assistant-tabs"><button :class="{active:tab==='chat'}" @click="tab='chat'">智能问答</button><button :class="{active:tab==='guide'}" @click="tab='guide'">操作指南</button></nav>
  <div v-show="tab==='chat'" class="chat-body">
   <div ref="log" class="messages" role="log" aria-live="polite"><div class="message assistant">{{welcome}}</div><div v-for="(m,i) in messages" :key="i" class="message" :class="m.role">{{m.content}}</div><div v-if="busy" class="thinking" role="status" aria-label="C豆正在思考"><i/><i/><i/></div><div v-if="failure" role="alert" class="chat-error">{{failure}}<el-button link :disabled="busy" @click="retry">重试</el-button></div>
   <details v-if="messages.length===0" class="quick" open><summary>试着问问 C豆</summary><button v-for="q in questions" :key="q" :disabled="busy" @click="send(q)">{{q}}</button></details></div>
   <div class="composer"><p>问题将发送至 MiMo，请勿输入客户机密。仅知识问答。</p><textarea ref="input" v-model="draft" aria-label="向 C豆提问" placeholder="输入录单问题…" maxlength="2000" rows="2" :disabled="busy||!!failure" @keydown="key"/><div class="compose-actions"><el-button link :disabled="busy" @click="clear">清空对话</el-button><span>{{draft.length}}/2000</span><el-button type="primary" :loading="busy" :disabled="!draft.trim()||!!failure" @click="send()">发送</el-button></div><small v-if="failure">可重试，或清空对话后重新提问。</small></div>
  </div>
  <div v-show="tab==='guide'" class="embedded-guide"><OperationGuide embedded/></div>
 </section></Transition>
</div>
</template>
<style scoped>
.cdou{font-size:13px;color:#324a66}.pet{position:fixed;left:0;top:0;width:76px;height:76px;z-index:1901;border:0;background:transparent;padding:0;touch-action:none;cursor:grab;user-select:none}.pet:focus-visible{outline:2px solid #2675e9;border-radius:20px}.pet-hover{display:block;transition:transform .2s}.pet:hover .pet-hover{transform:scale(1.07)}.pet:active{cursor:grabbing}.bouncing{animation:pet-tap .3s ease-out}@keyframes pet-tap{50%{transform:translateY(-4px) scale(1.04)}}.pet img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 5px 5px #264f7828);animation:idle 9s ease-in-out infinite}.dragging .pet img,.paused .pet img{animation-play-state:paused}.pet-bubble{position:fixed;z-index:1900;background:white;border:1px solid #dfebfc;border-radius:14px;padding:12px;box-shadow:0 4px 18px #24497614;pointer-events:none;width:204px;box-sizing:border-box}.assistant-panel{position:fixed;z-index:1902;width:min(390px,calc(100vw - 16px));height:min(560px,calc(100dvh - 16px));background:white;border:1px solid #dde7f4;border-radius:18px;box-shadow:0 12px 55px #203a6233;display:flex;flex-direction:column;overflow:hidden}.assistant-panel header{display:flex;align-items:center;gap:10px;padding:15px;background:linear-gradient(125deg,#edf5ff,#fafcff)}header img{width:40px;height:40px;border-radius:12px}header strong{font-size:15px}header small{display:block;margin-top:4px;color:#8291a6}header button{margin-left:auto;border:0;background:transparent;color:#697f99;font-size:25px;cursor:pointer}.assistant-tabs{display:flex;border-bottom:1px solid #edf1f7;padding:0 16px;gap:22px}.assistant-tabs button{padding:12px 0;border:0;background:transparent;color:#7c8ba0;cursor:pointer}.assistant-tabs .active{color:#2674d7;border-bottom:2px solid #2674d7}.chat-body{display:flex;flex-direction:column;flex:1;min-height:0}.messages{flex:1;overflow-y:auto;padding:16px;overscroll-behavior:contain}.message{padding:11px 13px;border-radius:12px;margin-bottom:12px;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;max-width:92%;width:fit-content;box-sizing:border-box}.assistant{background:#f1f5fb}.user{background:#e5efff;margin-left:auto;color:#235b9a}.quick{margin-top:20px;max-height:150px;overflow:auto}.quick summary{color:#8b9bb0;margin-bottom:10px}.quick button{display:block;text-align:left;background:white;border:1px solid #e7edf5;border-radius:8px;padding:8px 10px;color:#557395;margin:6px 0;cursor:pointer}.composer{border-top:1px solid #edf1f6;padding:10px 14px}.composer p{font-size:11px;color:#8c9aac;margin:0 0 8px}.composer textarea{width:100%;box-sizing:border-box;resize:none;border:1px solid #dbe5f2;border-radius:9px;padding:10px;font:inherit;color:inherit}.compose-actions{display:flex;align-items:center;gap:12px;margin-top:7px}.compose-actions span{margin-left:auto;color:#9ba8b8;font-size:11px}.embedded-guide{flex:1;min-height:0}.thinking{display:flex;gap:5px;padding:15px}.thinking i{width:6px;height:6px;border-radius:50%;background:#7da4d6;animation:think 1.3s infinite}.thinking i:nth-child(2){animation-delay:.15s}.thinking i:nth-child(3){animation-delay:.3s}.chat-error{color:#ab5d40;line-height:1.8;background:#fff6ee;padding:10px;border-radius:8px}.soft-enter-active,.soft-leave-active{transition:opacity .18s,transform .18s}.soft-enter-from,.soft-leave-to{opacity:0;transform:translateY(6px) scale(.98)}@keyframes idle{0%,100%{transform:translateY(0) rotate(0)}35%{transform:translateY(-3px) rotate(-1.5deg)}70%{transform:translateY(-1px) rotate(1deg)}}@keyframes think{50%{transform:translateY(-3px);opacity:.45}}.paused .thinking i{animation-play-state:paused}@media(prefers-reduced-motion:reduce){.pet img,.thinking i,.bouncing{animation:none}.pet-hover,.soft-enter-active,.soft-leave-active{transition:none}}@media(max-height:450px){.assistant-panel header{padding:8px}.composer{padding:6px 10px}}
</style>
